from pathlib import Path
O=Path(__file__).resolve().parent;D=O/'reductions/mean';D.mkdir(parents=True,exist_ok=True)
s=(O/'match_prod_production.py').read_text().replace("'prod'","'mean'").replace('cub_reduce_product_f32','cub_reduce_value_sum_f64').replace('matches/prod/','matches/mean/');(O/'match_mean_production.py').write_text(s)
s=(O/'build_prod_gpu.py').read_text().replace('reductions/prod','reductions/mean').replace('aten_prod','aten_mean').replace('cub_reduce_product_f32','cub_reduce_value_sum_f64').replace('static float parameters','static double parameters').replace('float*','double*').replace('float **','double **').replace('polygeist_cub_reduce_value_sum_f64(256,1.0f,p[0],p[1]);','double result=polygeist_cub_reduce_value_sum_f64(256,0.0,p[0]);p[1][0]=result/256.0;').replace("tail=(O/'ternary_harness.c').read_text()","tail=(O/'mean_harness_tail.c').read_text()")
(O/'build_mean_gpu.py').write_text(s)
t=(O/'ternary_harness.c').read_text().replace('float','double').replace('1e-5+1e-4','1e-12+1e-10')
t=t.replace('CU(cudaMalloc((void**)&d[a],bytes));','if(!outputs[a])CU(cudaMalloc((void**)&d[a],bytes));')
t=t.replace('CU(cudaMemcpy(d[a],h[a],bytes,cudaMemcpyHostToDevice));','if(!outputs[a])CU(cudaMemcpy(d[a],h[a],bytes,cudaMemcpyHostToDevice));')
t=t.replace('d[a]+=4;h[a]+=4;r[a]+=4;v[a]+=4;','h[a]+=4;r[a]+=4;v[a]+=4;if(outputs[a])d[a]=h[a];else d[a]+=4;')
t=t.replace('for(int a=0;a<NA;a++)CU(cudaMemcpy(v[a]-4,d[a]-4,(sizes[a]+8)*sizeof(double),cudaMemcpyDeviceToHost));','for(int a=0;a<NA;a++){size_t bytes=(sizes[a]+8)*sizeof(double);if(outputs[a])memcpy(v[a]-4,h[a]-4,bytes);else CU(cudaMemcpy(v[a]-4,d[a]-4,bytes,cudaMemcpyDeviceToHost));}')
t=t.replace('if(resident)CU(cudaMemcpy(got,d[a]-4,bytes,cudaMemcpyDeviceToHost));','if(resident&&!outputs[a])CU(cudaMemcpy(got,d[a]-4,bytes,cudaMemcpyDeviceToHost));')
(O/'mean_harness_tail.c').write_text('/* Scalar-return API: resident mode keeps input on device and scalar output on host. */\n'+t)
s=(O/'run_prod_gpu.py').read_text().replace('reductions/prod','reductions/mean').replace('aten-cub-reduction-production','aten-cub-mean-production').replace("baseline='direct CUB API; not native ATen'","baseline='direct CUB scalar-return API plus same host division/store; not native ATen',residency='device input, host scalar output'")
(O/'run_mean_gpu.py').write_text(s)
